    return { metrics };
  }

  const { state, payloadDef } = resolveApplyPayload(ctx.query, {
    actor,
    toolId,
    targetId,
  });
  if (payloadDef) {
    metrics.payloadMatched = true;
    metrics.path = "payload";
    const hookOut = runApplyHooks(ctx, payloadDef, state);
    if (ctx.cancelled) {
      return {
        metrics,
        payload: {
          defId: String(payloadDef.id || ""),
          hooks: hookOut,
