  const fallbackTo = { x: fallbackFrom.x + 1, y: fallbackFrom.y };
  const rec = (input && typeof input === "object") ? input : {};

  const from = normalizePoint(rec.from, fallbackFrom);
  const to = normalizePoint(rec.to, fallbackTo);
