 * @param {object} [def.bonuses] - { attack, defense, accuracy, ... }
 * @param {string} [def.damageDice] - "1d8"
 * @param {string} [def.damageType] - "slash", "blunt", "pierce"
 * @param {number} [def.staminaCost]
