        ctx.mutate.queue({
          type: "damage",
          entityId: hitId,
          amount: damage,
          source: actorId,
          damageType,
        });
      }
      if (healPct > 0) {
        const vit = ctx.query.get(hitId, Vitality);
        if (vit) {
