          key: effectKey,
          potency,
          turnsLeft: duration,
          onsetLeft: 0,
          peakLeft: 0,
          stack: "refresh",
          maxStacks: 1,
          sourceId: itemId,
          meta: { source: sourceKind, delivery: "splash" },
        });
      }
    }

    if (hazardKind) {
      ctx.helpers.hazardSpawn({
        kind: hazardKind,
        medium: "floor",
        turnsLeft: hazardTurns,
        radius: 0,
        tickDamage: hazardTickDmg,
        damageType,
        cause: "potion_splash",
        sourceId: actorId,
